// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«המסע שלי»', () => {
  test('JR-05 «מקבל על עצמי» открыт во время загрузки — поле заблокировано, затем само показывает קבלה #31c88137 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран

    // 1. До перехода: GET personal_commitments удерживается, пока тест не проверит состояние «во время загрузки»
    //    (затем release(); страховка — авто-release через 60 с); прочие методы без задержки; записываем мутации.
    let release!: () => void;
    const released = new Promise<void>((resolve) => {
      release = resolve;
    });
    const safetyRelease = setTimeout(() => release(), 60_000);
    const mutations: string[] = [];
    page.on('request', (req) => {
      if (req.url().includes('/rest/v1/personal_commitments') && ['POST', 'PATCH', 'DELETE'].includes(req.method())) {
        mutations.push(`${req.method()} ${req.url()}`);
      }
    });
    await page.route('**/rest/v1/personal_commitments**', async (route) => {
      if (route.request().method() === 'GET') {
        await released;
      }
      await route.continue();
    });

    // 2. Открыть `/journey`; как только видна «טוענים את הקבלה האישית…» — раскрыть «מקבל על עצמי».
    await page.goto('/journey');
    const loading = page.getByText('טוענים את הקבלה האישית…');
    await expect(loading).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await page.getByRole('button', { name: /^מקבל על עצמי/ }).click();

    // 3. Пока строка загрузки видна — проверить поле и кнопки, кликнуть «שמירה» (force).
    const field = page.getByRole('textbox', { name: 'מקבל על עצמי' });
    await expect(loading).toBeVisible();
    await expect(field).toBeVisible();
    await expect(field).toBeDisabled({ timeout: 2_000 }).catch(async () => {
      await expect(field).not.toBeEditable();
    });
    const save = page.getByRole('button', { name: 'שמירה' });
    await expect(save).toHaveAttribute('aria-disabled', 'true');
    await expect(page.getByRole('button', { name: 'הסרת הקבלה' })).toHaveCount(0);
    await save.click({ force: true });
    expect(mutations).toEqual([]);
    await expect(loading).toBeVisible();

    // 4. Отпустить удержанный GET; не трогая поле, дождаться исчезновения «טוענים את הקבלה האישית…».
    release();
    clearTimeout(safetyRelease);
    await expect(loading).toHaveCount(0, { timeout: 30_000 });
    await expect(field).toHaveValue('test');
    await expect(field).toBeEditable();
    await expect(save).not.toHaveAttribute('aria-disabled', 'true');
    await expect(page.getByRole('button', { name: 'הסרת הקבלה' })).toBeVisible();
    expect(mutations).toEqual([]);
  });
});
